  bool isFirstElement = true; // Flag to check if it's the first element in the list

  for (var i = 0; i < l.length; ++i) {
    var currentVal = l[i];

    if (!isFirstElement && currentVal == prevValue) continue; // Skip duplicates

    sortedUnique.add(currentVal); // Add the current number to the result list
    prevValue = currentVal; // Update previous value
    isFirstElement = false; // Mark that we have processed at least one element
  }

  return sortedUnique; // Return the list of unique values
}

