List<int> maximum(List<int> arr, int k) {
  // Create a max-heap using the negative values for min-heap behavior.
  List<int> heap = [];

  // Helper function to maintain the heap property (min-heap).
  void siftDown(int index) {
    while (true) {
      int leftChildIndex = 2 * index + 1;
      if (leftChildIndex >= heap.length) break;
      int rightChildIndex = leftChildIndex + 1;

      // Find the smallest child.
      int smallestChildIndex = leftChildIndex;
      if (rightChildIndex < heap.length && 
          -heap[rightChildIndex] > -heap[smallestChildIndex]) {
        smallestChildIndex = rightChildIndex;
      }

      // If current node is larger than its smallest child, swap them.
      if (-heap[index] > -heap[smallestChildIndex]) {
        int temp = heap[index];
        heap[index] = heap[smallestChildIndex];
        heap[smallestChildIndex] = temp;
        index = smallestChildIndex;
      } else {
        break;
      }
    }
  }

  // Insert elements into the heap and keep only the top 'k' largest elements.
  for (int num in arr) {
    if (heap.length < k) {
      heap.add(num);
      siftDown(0); // Maintain heap property after insertion.
    } else if (num > heap[0]) { // Replace the smallest element with this one.
      heap[0] = num;
      siftDown(0);
    }
  }

  return heap;
}

