  if (lst.isEmpty || lst.length <= 1) return [];

  int totalLength = 0;
  for (String s in lst) {
    totalLength += s.length;
  }

  List<int> charCounts = [0] * totalLength;
  Map<String, bool> seenChars = {};

  for (int i = 0; i < lst.length; i++) {
    String word = lst[i];

    // Check if any character already exists in this position from previous words
    for (int j = 0; j < word.length && !seenChars.containsKey(word[j]); j++) {
      int pos = totalLength - word.length + j;

      if (!charCounts[pos]) {
