      }
    }

    if (i == lst.length - 1) {
      // If we're at the last word and all positions are filled, sort by length
      if (totalLength > 0) {
        lst.sort((a,b) => a.length.compareTo(b.length));

        // Remove duplicates while maintaining order
        final result = <String>[];
        for(String w : lst){
