  List<int> lengths = [0] * totalLength;
  for (int i = 0; i < lst.length; i++) {
    String s = lst[i];
    for (int j = 0; j < s.length; j++) {
      lengths[i + j] += s[j].codeUnitAt(0);
    }
  }


  List<List<int>> counts = new List.generate(lengths.length, (_) => []);
  for (int i = 0; i < lengths.length; i++) {
    for (int c : ['A', 'B', 'C', 'D'].map(String.fromCharCode).toList()) {
      if (c.codeUnitAt(0) == lengths[i]) {
        counts[i].add(c);
      }
    }
  }

  List<String> result = [];
  bool used[] = new bool[lengths.length];
  void backtrack(int index) {
    if (index == counts.length) {
      result.add(counts.fold('', (acc, group) => acc + group.join('')));
      return;
    }

    for (String char in counts[index]) {
      if (!used[index - char.codeUnitAt(0)]) {
        used[index - char.codeUnitAt(0)] = true;
        backtrack(index - char.codeUnitAt(0));
        used[index - char.codeUnitAt(0)] = false;
      }
    }
  }

  backtrack(totalLength / 2);
  return result.reversed.toList();
}

